DECLARE
  l_dept_with_rows        NUMBER;
  l_dept_no_rows          NUMBER;
  l_expected_match        NUMBER;
  l_actual_match          NUMBER;
  l_expected_nomatch      NUMBER;
  l_actual_nomatch        NUMBER;
  l_null_arg              NUMBER := NULL;
  l_expected_null         NUMBER;
  l_actual_null           NUMBER;
  l_failures              PLS_INTEGER := 0;

  PROCEDURE check_result(
    p_label    IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE('PASS: ' || p_label ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: ' || p_label ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
      l_failures := l_failures + 1;
    END IF;
  END check_result;
BEGIN
  SAVEPOINT sp_test;

  -- Find a department_id that should match at least one row.
  SELECT MIN(department_id)
    INTO l_dept_with_rows
    FROM employees
   WHERE department_id IS NOT NULL;

  -- Check 1: matching key, if one exists.
  IF l_dept_with_rows IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: matching-key check expected a non-null department_id with at least one employee row, but setup found none');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_match
      FROM employees
     WHERE department_id = l_dept_with_rows;

    l_actual_match := harness_app.headcount(l_dept_with_rows);

    check_result(
      p_label    => 'matching department_id',
      p_expected => l_expected_match,
      p_actual   => l_actual_match
    );
  END IF;

  -- Find a non-null department_id that should match no row.
  -- If a matching key exists, one less than the minimum non-null value
  -- is guaranteed not to match any existing non-null department_id.
  IF l_dept_with_rows IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: no-match-key check expected a non-null department_id with no employee rows, but setup found no non-null department_id from which to derive one');
    l_failures := l_failures + 1;
  ELSE
    l_dept_no_rows := l_dept_with_rows - 1;

    SELECT COUNT(*)
      INTO l_expected_nomatch
      FROM employees
     WHERE department_id = l_dept_no_rows;

    IF l_expected_nomatch <> 0 THEN
      DBMS_OUTPUT.PUT_LINE('FAIL: no-match-key check expected department_id=' || l_dept_no_rows || ' to match no rows, but setup found ' || l_expected_nomatch || ' row(s)');
      l_failures := l_failures + 1;
    ELSE
      l_actual_nomatch := harness_app.headcount(l_dept_no_rows);

      check_result(
        p_label    => 'non-matching department_id',
        p_expected => l_expected_nomatch,
        p_actual   => l_actual_nomatch
      );
    END IF;
  END IF;

  -- Check 3: NULL argument. The function compares department_id = p_department_id,
  -- so a NULL argument matches no rows, even if department_id IS NULL exists.
  SELECT COUNT(*)
    INTO l_expected_null
    FROM employees
   WHERE department_id = l_null_arg;

  l_actual_null := harness_app.headcount(l_null_arg);

  check_result(
    p_label    => 'NULL argument',
    p_expected => l_expected_null,
    p_actual   => l_actual_null
  );

  DBMS_OUTPUT.PUT_LINE('Summary: failures=' || l_failures);

  ROLLBACK TO sp_test;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount test block failed with ' || l_failures || ' failure(s)'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: unexpected error: ' || SQLERRM);
    ROLLBACK TO sp_test;
    RAISE;
END;
```

The block checks three cases:

1. A matching `department_id`: it selects a non-null `department_id` from `employees`, computes the expected count with an independent `SELECT COUNT(*)`, calls `harness_app.headcount`, and compares the result. If setup finds no non-null `department_id` with rows, the check prints `FAIL` and counts as a failure.

2. A non-matching non-null `department_id`: if a matching key was found, it uses one less than the minimum non-null `department_id`, confirms independently that it matches no rows, calls `harness_app.headcount`, and compares the result. If setup cannot produce such a key, the check prints `FAIL` and counts as a failure.

3. A `NULL` argument: it computes the expected result using the same comparison style as the function, `department_id = NULL`, which matches no rows, then calls `harness_app.headcount(NULL)` and compares the result.

The block starts with `SAVEPOINT sp_test`, rolls back to that savepoint at the end, and in its exception handler prints the unexpected error, rolls back to the savepoint, and re-raises. It does not commit. I have not run this block.

